package com.nigson.experience.lead;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import com.nigson.shared.security.PrivateWorkload;

/** Experience-owned lead context and acknowledged quote association for Commerce. */
public final class QuoteLeadAssociation {
 public interface SkuEligibilityPort { List<QuoteLeadValues.EligibleSku> validate(UUID party,UUID market,UUID organization,List<QuoteLeadValues.Product> products); }
 public record Context(UUID id,UUID partyId,UUID organizationId,String state){}
 public record AssociationInput(UUID commandId,UUID quoteId,String quoteState){ public AssociationInput{if(commandId==null||quoteId==null||commandId.equals(new UUID(0,0))||quoteId.equals(new UUID(0,0))||!Set.of("DRAFT","OFFERED","ACCEPTED","REJECTED","EXPIRED","CANCELLED").contains(quoteState))throw ApiValues.invalid();} }
 public record Acknowledgement(boolean acknowledged){}
 private final JdbcTemplate jdbc;private final PlatformStore store;private final AuditWriter audit;private final Clock clock;private final SkuEligibilityPort skus;private final String recipientGroup;
 public QuoteLeadAssociation(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,Clock clock,SkuEligibilityPort skus,String recipientGroup){this.jdbc=jdbc;this.store=store;this.audit=audit;this.clock=clock;this.skus=skus;this.recipientGroup=recipientGroup;}
 private static PrivateWorkload.Route route(String api){return PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.owner().equals("experience")&&r.client().equals("nigson-commerce")).findFirst().orElseThrow(ActorAssertion::denied);}
 private static void require(PrivateWorkload.Proof proof,String api){if(proof==null||proof.actor()!=null||!route(api).equals(proof.route())||proof.subject()==null||proof.subject().isBlank())throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private ActorAssertion.Actor customer(PrivateWorkload.Proof proof){var r=PrivateWorkload.ROUTES.stream().filter(x->x.api().equals("API-088")&&x.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||!r.equals(proof.route())||!"nigson-commerce".equals(proof.client())||proof.actor()==null||proof.actor().organization()!=null||!proof.actor().roles().contains("CUSTOMER")||!proof.actor().scopes().contains(r.scope()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return proof.actor();}
 public QuoteLeadValues.Created create(PrivateWorkload.Proof proof,QuoteLeadValues.Request input,String key,UUID correlation){var actor=customer(proof);if(input==null||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(input);var replay=store.replayLocal(actor.party().toString(),"API-088",key,request);if(replay.isPresent())return EventCodec.JSON.treeToValue(replay.get().body(),QuoteLeadValues.Created.class);if(recipientGroup==null||recipientGroup.isBlank())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(skus==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);skus.validate(actor.party(),input.marketId(),input.organizationId(),input.products());UUID id=EventCodec.uuid7(clock.instant());var saved=store.executeLocal(actor.party().toString(),"API-088",key,request,db->{Instant now=clock.instant();db.update("INSERT INTO experience.lead(id,created_by,updated_by,type,party_id,organization_id,name,email,phone,subject,message,status,priority,source) VALUES (?, ?, ?, 'QUOTE', ?, ?, ?, ?, ?, ?, ?, 'NEW', 'NORMAL', 'WEB_QUOTE_REQUEST')",id,actor.party().toString(),actor.party().toString(),actor.party(),input.organizationId(),input.contact().name(),input.contact().email(),input.contact().phone(),input.subject(),input.message());for(var item:input.products())db.update("INSERT INTO experience.lead_requested_item(id,created_by,updated_by,lead_id,sku_id,quantity) VALUES (?,?,?,?,?,?)",EventCodec.uuid7(now),actor.party().toString(),actor.party().toString(),id,item.skuId(),item.quantity());appendLeadCreated(id,correlation,actor.party().toString());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUOTE_CREATE,AuditValues.Resource.LEAD,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("state","NEW","requestedItemCount",input.products().size()),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new QuoteLeadValues.Created(id,"NEW")),id);});return EventCodec.JSON.treeToValue(saved.body(),QuoteLeadValues.Created.class);}
 private void appendLeadCreated(UUID id,UUID correlation,String actor){Instant now=clock.instant();var event=new LinkedHashMap<String,Object>();event.put("event_id",EventCodec.uuid7(now));event.put("event_type","lead.created.v1");event.put("schema_version",1);event.put("producer","experience");event.put("occurred_at",now.toString());event.put("aggregate_id",id);event.put("aggregate_version",0);event.put("organization_id",null);event.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();event.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);event.put("payload",Map.of("lead_id",id,"type","QUOTE","priority","NORMAL","recipient_group",recipientGroup));store.append(EventCodec.JSON.writeValueAsString(event),actor);}
 public Context read(PrivateWorkload.Proof proof,UUID leadId){require(proof,"API-130");if(leadId==null||leadId.equals(new UUID(0,0)))throw ApiValues.invalid();var rows=jdbc.query("SELECT id,party_id,organization_id,status,type FROM experience.lead WHERE id=? AND type='QUOTE'",(r,n)->new Context(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4)),leadId);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 public Acknowledgement associate(PrivateWorkload.Proof proof,UUID leadId,AssociationInput input,UUID correlation){require(proof,"API-131");if(leadId==null||leadId.equals(new UUID(0,0))||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var response=store.executeLocal("service:nigson-commerce","API-131",input.commandId().toString(),EventCodec.JSON.valueToTree(Map.of("leadId",leadId,"input",input)),db->{var rows=jdbc.queryForList("SELECT id,related_quote_id,version FROM experience.lead WHERE id=? AND type='QUOTE' FOR UPDATE",leadId);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();Object existing=row.get("related_quote_id");UUID old=existing instanceof UUID v?v:null;if(old!=null&&!old.equals(input.quoteId()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(old==null){int changed=jdbc.update("UPDATE experience.lead SET related_quote_id=?,version=version+1,updated_at=?,updated_by='nigson-commerce' WHERE id=? AND version=? AND related_quote_id IS NULL",input.quoteId(),java.sql.Timestamp.from(clock.instant()),leadId,row.get("version"));if(changed!=1)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);audit.append("nigson-commerce",AuditValues.ActorKind.SERVICE,AuditValues.Action.QUOTE_ASSOCIATION,AuditValues.Resource.LEAD,leadId,correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("version",row.get("version")),Map.of("state",input.quoteState()),null);}return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Acknowledgement(true)),input.commandId());});return EventCodec.JSON.treeToValue(response.body(),Acknowledgement.class);}
}
